const QUERY_FUNCTION_NAMES = [
  'In',
  'NotIn',
  'Between',
  'NotBetween',
  'ContainValues',
  'DoesNotContainValues',
  'EqualUserId',
  'NotEqualUserId',
  'EqualUserLanguage',
  'EqualUserAuthContext',
  'On',
  'OnOrAfter',
  'OnOrBefore',
  'Today',
  'Yesterday',
  'Tomorrow',
  'Last7Days',
  'Next7Days',
  'LastWeek',
  'ThisWeek',
  'NextWeek',
  'LastMonth',
  'ThisMonth',
  'NextMonth',
  'LastYear',
  'ThisYear',
  'NextYear',
  'LastXHours',
  'NextXHours',
  'LastXDays',
  'NextXDays',
  'LastXWeeks',
  'NextXWeeks',
  'LastXMonths',
  'NextXMonths',
  'LastXYears',
  'NextXYears',
  'OlderThanXMinutes',
  'OlderThanXHours',
  'OlderThanXDays',
  'OlderThanXWeeks',
  'OlderThanXMonths',
  'OlderThanXYears',
  'InFiscalYear',
  'InFiscalPeriod',
  'InFiscalPeriodAndYear',
  'InOrBeforeFiscalPeriodAndYear',
  'InOrAfterFiscalPeriodAndYear',
  'ThisFiscalYear',
  'ThisFiscalPeriod',
  'NextFiscalYear',
  'NextFiscalPeriod',
  'LastFiscalYear',
  'LastFiscalPeriod',
  'LastXFiscalYears',
  'LastXFiscalPeriods',
  'NextXFiscalYears',
  'NextXFiscalPeriods',
  'Above',
  'AboveOrEqual',
  'Under',
  'UnderOrEqual',
  'NotUnder',
  'EqualUserOrUserHierarchy',
  'EqualUserOrUserHierarchyAndTeams',
  'EqualUserOrUserTeams',
  'EqualUserTeams',
  'EqualBusinessId',
  'NotEqualBusinessId',
  'Contains',
  'EqualRoleBusinessId',
];

const escapeXml = (text) =>
  String(text).replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const render = ([tag, attrs, ...children]) => {
  const attributes = Object.entries(attrs)
    .map(([name, value]) => ` ${name}="${escapeXml(value)}"`)
    .join('');
  return children.length ? `<${tag}${attributes}>${children.map(render).join('')}</${tag}>` : `<${tag}${attributes} />`;
};
const attrsOf = (text) =>
  Object.fromEntries([...text.matchAll(/([\w:]+)="([^"]*)"/g)].map((match) => [match[1], match[2]]));
const keyOf = ([tag, attrs, ...children]) =>
  [tag, attrs.Name, attrs.IsBound === 'true' ? children.find((child) => child[0] === 'Parameter')?.[1].Type : ''].join(
    ':',
  );
const operations = new Map(PLATFORM_OPERATIONS.map((contract) => [keyOf(contract), contract]));
const types = new Map(PLATFORM_TYPES.map((contract) => [contract[1].Name, contract]));
const references = (text) =>
  [...text.matchAll(/\b(?:Type|BaseType|EntityType)="(?:Collection\()?mscrm\.([\w]+)/g)].map((match) => match[1]);
const OPERATION = /<(Action|Function)\b([^>]*?)(?:\/>|>([\s\S]*?)<\/\1>)/g;
const TYPE = /<(ComplexType|EnumType|EntityType)\b([^>]*?)(?:\/>|>([\s\S]*?)<\/\1>)/g;

/** Canonical platform declarations; unknown/custom operations keep their own signatures and execution handlers. */
export function platformOperationCsdl(input, registration = null) {
  return String(input).replace(OPERATION, (original, tag, attributes, body = '') => {
    const attrs = attrsOf(attributes);
    const binding = attrs.IsBound === 'true' ? attrsOf(body.match(/<Parameter\b([^>]*?)\/>/)?.[1] ?? '').Type : '';
    // The registry's binding is authoritative; older extension helpers may have emitted an entity parameter for a set.
    const registered =
      registration?.name === attrs.Name && (registration.kind === 'action' ? 'Action' : 'Function') === tag;
    const type = registration?.entity === '*' ? 'mscrm.crmbaseentity' : `mscrm.${registration?.entity}`;
    const registeredBinding =
      registration?.binding === 'collection' ? `Collection(${type})` : registration?.binding === 'entity' ? type : '';
    const contract = operations.get([tag, attrs.Name, registered ? registeredBinding : binding].join(':'));
    return contract ? render(contract) : original;
  });
}

/** Deduplicate the structured parameter/result types and add only the dependencies referenced by the assembled model. */
export function platformCsdl(input, { queryFunctions = false } = {}) {
  let text = platformOperationCsdl(input);
  if (queryFunctions) {
    const declared = new Set([...text.matchAll(/<Function\b[^>]*\bName="([^"]+)"/g)].map((match) => match[1]));
    const names = new Set(QUERY_FUNCTION_NAMES);
    text +=
      '\n' +
      PLATFORM_OPERATIONS.filter(
        (contract) => contract[0] === 'Function' && names.has(contract[1].Name) && !declared.has(contract[1].Name),
      )
        .map(render)
        .join('\n');
  }
  text = text.replace(TYPE, (original, _tag, attributes) => (types.has(attrsOf(attributes).Name) ? '' : original));
  const pending = references(text),
    needed = new Map();
  while (pending.length) {
    const name = pending.pop(),
      type = types.get(name);
    if (!type || needed.has(name)) continue;
    const xml = render(type);
    needed.set(name, xml);
    pending.push(...references(xml));
  }
  const declarations = [...needed.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([, xml]) => xml)
    .join('\n');
  return declarations ? declarations + '\n' + text : text;
}
